import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S07/S07E11.html","title":"S07E11 The One with All the Cheesecakes","lang":"zh-CN","frontmatter":{"title":"S07E11 The One with All the Cheesecakes","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":157},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":37.17,"words":11150},"filePathRelative":"语言/英语/Friends老友记/S07/S07E11.md"}`),l={name:`S07E11.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-all-the-cheesecakes" tabindex="-1"><a class="header-anchor" href="#the-one-with-all-the-cheesecakes"><span>The One with All the Cheesecakes</span></a></h1><blockquote><p><em>有所有奶酪蛋糕的那个</em></p></blockquote><p>The One With All The Cheesecakes</p><blockquote><p>那个有所有芝士蛋糕的</p></blockquote><p><strong>Written by: Shana Goldberg-Meehan</strong></p><blockquote><p>作者：沙娜·戈德伯格·米汉</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote>`,8),r(p,{src:`/audio/friends/S07/S07E11/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`With Help from:`,-1),c[3]||=i(` Aaron Howard-Miller`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`亚伦·霍华德·米勒`)],-1),c[5]||=a(`hr`,null,null,-1),c[6]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Monica’s, Chandler is sitting at the kitchen table eating cheesecake. The box it came in is also on the table.`)],-1),c[7]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和莫妮卡家，钱德勒正坐在厨房桌子旁吃奶酪蛋糕。它进来的盒子也在桌子上。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/002.mp3`}),c[8]||=i(),c[9]||=a(`strong`,null,`Chandler Bing:`,-1),c[10]||=i(` Ohh. Mmm.`,-1),c[11]||=a(`blockquote`,null,[a(`p`,null,`哦。嗯。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/003.mp3`}),c[12]||=i(),c[13]||=a(`strong`,null,`Rachel Green:`,-1),c[14]||=i(` (Comes in the front door and walks towards the kitchen.) Hi.`,-1),c[15]||=a(`blockquote`,null,[a(`p`,null,`（从前门进来，朝厨房走去。）嗨。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/004.mp3`}),c[16]||=i(),c[17]||=a(`strong`,null,`Chandler Bing:`,-1),c[18]||=i(` Hey, you have got to try this cheesecake.`,-1),c[19]||=a(`blockquote`,null,[a(`p`,null,`嘿，你得尝尝这个芝士蛋糕。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/005.mp3`}),c[20]||=i(),c[21]||=a(`strong`,null,`Rachel Green:`,-1),c[22]||=i(` Oh, y’know I'm not that much of a sweet tooth. I—(Chandler puts a forkful of the cheesecake in her mouth.)—Wow. My God, so creamy. Oh my God, this is the best cheesecake I have ever had. Where did you get this? (She reaches over to look at the label on the box.)`,-1),c[23]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道我不太喜欢吃甜食。我-（钱德勒把一叉奶酪蛋糕放进她的嘴里。）-哇。我的天啊，好滑啊。天哪，这是我吃过的最好的奶酪蛋糕。你从哪儿弄来的？（她伸手看了看盒子上的标签。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/006.mp3`}),c[24]||=i(),c[25]||=a(`strong`,null,`Chandler Bing:`,-1),c[26]||=i(` (nervously) It was at the front door. When I got home. Somebody sent it to us.`,-1),c[27]||=a(`blockquote`,null,[a(`p`,null,`（紧张地）在前门。当我到家的时候。有人寄给我们的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/007.mp3`}),c[28]||=i(),c[29]||=a(`strong`,null,`Rachel Green:`,-1),c[30]||=i(` Chandler, this is not addressed to you. This is addressed to Mrs. Braverman downstairs. (Gasping) Thief.`,-1),c[31]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，这不是写给你的。这是写给楼下的Braverman太太的。（喘息）小偷。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/008.mp3`}),c[32]||=i(),c[33]||=a(`strong`,null,`Chandler Bing:`,-1),c[34]||=i(` I—no! I didn't read the box before I opened it. And you can't return a box after you've opened the box.`,-1),c[35]||=a(`blockquote`,null,[a(`p`,null,`不！我打开盒子之前没有读过。而且你不能在打开箱子后还箱子。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/009.mp3`}),c[36]||=i(),c[37]||=a(`strong`,null,`Rachel Green:`,-1),c[38]||=i(` Why, why not?`,-1),c[39]||=a(`blockquote`,null,[a(`p`,null,`为什么，为什么不呢？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/010.mp3`}),c[40]||=i(),c[41]||=a(`strong`,null,`Chandler Bing:`,-1),c[42]||=i(` Because it's too delicious.`,-1),c[43]||=a(`blockquote`,null,[a(`p`,null,`因为太好吃了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/011.mp3`}),c[44]||=i(),c[45]||=a(`strong`,null,`Rachel Green:`,-1),c[46]||=i(` Chandler, you stole this cheesecake. That is wrong.`,-1),c[47]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，你偷了这个芝士蛋糕。这是错误的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/012.mp3`}),c[48]||=i(),c[49]||=a(`strong`,null,`Chandler Bing:`,-1),c[50]||=i(` No-no-no! It is going to be okay, because Mrs. Braverman is gonna send away for a free one and that way we all win! The only losers are the big cheesecake conglomerate, (Reading the label) Momma’s Little Bakery. (Pause) I feel terrible, I’m a horrible, horrible, horrible person.`,-1),c[51]||=a(`blockquote`,null,[a(`p`,null,`不，不！一切都会好起来的，因为Braverman太太要送走一个免费的，这样我们都赢了！唯一的输家是大芝士蛋糕集团（阅读标签）妈妈的小面包店。（停顿）我感觉很糟糕，我是一个可怕、可怕、可怕的人。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/013.mp3`}),c[52]||=t(` <strong>Rachel Green:</strong> (taking a bite) Oh, I’m sorry what?<blockquote><p>（咬了一口）哦，对不起什么？</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, everyone except Rachel is there as Joey gets up and starts putting on his coat.</em></p><blockquote><p>🎬 <em>中央公园，乔伊起床开始穿外套时，除了瑞秋，其他人都在那里。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E11/014.mp3`}),c[53]||=i(),c[54]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[55]||=i(` All right, I should get going, big day a work. Y’know I’m in a coma? Today, they do this test on me and it turns out I’m not brain dead.`,-1),c[56]||=a(`blockquote`,null,[a(`p`,null,`好吧，我该走了，今天是重要的一天。你知道我昏迷了吗？今天，他们在我身上做了这个测试，结果证明我并没有脑死亡。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/015.mp3`}),c[57]||=i(),c[58]||=a(`strong`,null,`Chandler Bing:`,-1),c[59]||=i(` So…`,-1),c[60]||=a(`blockquote`,null,[a(`p`,null,`那么…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/016.mp3`}),c[61]||=i(),c[62]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[63]||=i(` Ah-ah-ah Mr. Smartie Pants, it’s just not my character that’s not brain dead. Hey, so Pheebs, we still on for tonight?`,-1),c[64]||=a(`blockquote`,null,[a(`p`,null,`啊，Smartie先生，不是我的角色没有脑死亡。嘿，菲比，我们今晚还有约会吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/017.mp3`}),c[65]||=i(),c[66]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[67]||=i(` Absolutely!`,-1),c[68]||=a(`blockquote`,null,[a(`p`,null,`当然！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/018.mp3`}),c[69]||=i(),c[70]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[71]||=i(` I’ll see you at 8:00.`,-1),c[72]||=a(`blockquote`,null,[a(`p`,null,`8点见。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/019.mp3`}),c[73]||=i(),c[74]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[75]||=i(` Okay. (Joey exits.)`,-1),c[76]||=a(`blockquote`,null,[a(`p`,null,`好的。（乔伊走了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/020.mp3`}),c[77]||=i(),c[78]||=a(`strong`,null,`Chandler Bing:`,-1),c[79]||=i(` Oh, what’s at 8:00?`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`哦，8点有什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/021.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[83]||=i(` Oh, I have dinner plans with Joey. We get together about once a month to discuss the rest of you guys.`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`哦，我和乔伊有晚餐计划。我们大约每个月聚一次，讨论你们其他人。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/022.mp3`}),c[85]||=i(),c[86]||=a(`strong`,null,`Ross Geller:`,-1),c[87]||=i(` Wow, did not know that! May I say how lovely you look today?`,-1),c[88]||=a(`blockquote`,null,[a(`p`,null,`哇，我不知道！我可以说你今天看起来多可爱吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/023.mp3`}),c[89]||=i(),c[90]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[91]||=i(` Duly noted.`,-1),c[92]||=a(`blockquote`,null,[a(`p`,null,`注意到了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/024.mp3`}),c[93]||=i(),c[94]||=a(`strong`,null,`Ross Geller:`,-1),c[95]||=i(` Thanks. (Phoebe gets up to get a refill.) (To Monica) Oh! So for tomorrow, do you want to rent a car and drive down together or what?`,-1),c[96]||=a(`blockquote`,null,[a(`p`,null,`谢谢。（菲比站起来要续杯。）（对莫妮卡）哦！那么明天，你想租辆车一起开车去吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/025.mp3`}),c[97]||=i(),c[98]||=a(`strong`,null,`Monica Geller:`,-1),c[99]||=i(` What are you talking about?`,-1),c[100]||=a(`blockquote`,null,[a(`p`,null,`你在说什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/026.mp3`}),c[101]||=i(),c[102]||=a(`strong`,null,`Ross Geller:`,-1),c[103]||=i(` Cousin Frannie’s wedding, its tomorrow night.`,-1),c[104]||=a(`blockquote`,null,[a(`p`,null,`弗兰尼表哥的婚礼，明晚举行。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/027.mp3`}),c[105]||=i(),c[106]||=a(`strong`,null,`Monica Geller:`,-1),c[107]||=i(` You were invited?!`,-1),c[108]||=a(`blockquote`,null,[a(`p`,null,`你被邀请了？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/028.mp3`}),c[109]||=i(),c[110]||=a(`strong`,null,`Ross Geller:`,-1),c[111]||=i(` No.`,-1),c[112]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/029.mp3`}),c[113]||=i(),c[114]||=a(`strong`,null,`Monica Geller:`,-1),c[115]||=i(` My God, I can’t believe this! I mean I knew that mom and dad were invited, but I thought that was it! I mean from the ages 7 to 9 Frannie and I were inseparable!`,-1),c[116]||=a(`blockquote`,null,[a(`p`,null,`天哪，我真不敢相信！我的意思是我知道爸爸妈妈被邀请了，但我想就是这样！我是说，从7岁到9岁，弗兰妮和我形影不离！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/030.mp3`}),c[117]||=i(),c[118]||=a(`strong`,null,`Chandler Bing:`,-1),c[119]||=i(` Well, maybe since the age of 9, Frannie’s made some new friends.`,-1),c[120]||=a(`blockquote`,null,[a(`p`,null,`嗯，也许从9岁起，弗兰妮交了一些新朋友。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/031.mp3`}),c[121]||=i(),c[122]||=a(`strong`,null,`Ross Geller:`,-1),c[123]||=i(` Well l-look okay, it’s probably just a mistake. Let me call Aunt Sheryl okay? Maybe you are invited and the invitation just got lost in the mail.`,-1),c[124]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，这可能只是个错误。让我给谢丽尔阿姨打电话好吗？也许你被邀请了，但邀请信在邮件中丢失了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/032.mp3`}),c[125]||=i(),c[126]||=a(`strong`,null,`Monica Geller:`,-1),c[127]||=i(` Yeah, well you call her and tell her that y’know when we were kids her precious little Frannie tried to undress me several times, okay? And if I hadn’t have stopped her, there probably wouldn’t even be a wedding to go too.`,-1),c[128]||=a(`blockquote`,null,[a(`p`,null,`是啊，你打电话给她，告诉她你知道，当我们还是孩子的时候，她可爱的小弗朗尼好几次想帮我脱衣服，好吗？如果我没有阻止她，可能连婚礼都不会举行了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/033.mp3`}),c[129]||=i(),c[130]||=a(`strong`,null,`Ross Geller:`,-1),c[131]||=i(` Y’know, she tried to undress me too.`,-1),c[132]||=a(`blockquote`,null,[a(`p`,null,`你知道，她也试着给我脱衣服。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/034.mp3`}),c[133]||=i(),c[134]||=a(`strong`,null,`Chandler Bing:`,-1),c[135]||=i(` I used to undress my cousin Glenn. (Monica looks at him then sushes him.)`,-1),c[136]||=a(`blockquote`,null,[a(`p`,null,`我过去常给我表妹格伦脱衣服。（莫妮卡看了他一眼，然后拍了拍他。）`)],-1),c[137]||=a(`hr`,null,null,-1),c[138]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, Monica, Chandler, Rachel, and Ross are playing Monopoly as Phoebe enters angrily.`)],-1),c[139]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋、莫妮卡、钱德勒、瑞秋和罗斯在扮演大富翁，菲比愤怒地走进来。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/035.mp3`}),c[140]||=i(),c[141]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[142]||=i(` Joseph Francis Tribbiani are you home yet?!!`,-1),c[143]||=a(`blockquote`,null,[a(`p`,null,`约瑟夫·弗朗西斯·特里比亚尼你回家了吗？！！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/036.mp3`}),c[144]||=i(),c[145]||=a(`strong`,null,`Rachel Green:`,-1),c[146]||=i(` Umm, I think he’s still out. What’s wrong?`,-1),c[147]||=a(`blockquote`,null,[a(`p`,null,`嗯，我想他还没回来。发生了什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/037.mp3`}),c[148]||=i(),c[149]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[150]||=i(` Well, I’ll tell you Rachel Karen Green, I had plans with Joey tonight and he left me this note. (Hands it to Rachel.)`,-1),c[151]||=a(`blockquote`,null,[a(`p`,null,`好吧，我告诉你瑞秋·凯伦·格林，我今晚和乔伊有安排，他给我留了这张纸条。（把它交给瑞秋。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/038.mp3`}),c[152]||=i(),c[153]||=a(`strong`,null,`Rachel Green:`,-1),c[154]||=i(` (reading the note) "Pheebs, can’t make it, got a date. Talk to you later. Big Daddy." (Laughs) Big Daddy?`,-1),c[155]||=a(`blockquote`,null,[a(`p`,null,`（读纸条）“菲比，不行了，有个约会。待会儿再跟你谈。大爸爸。”（笑）大爸爸？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/039.mp3`}),c[156]||=i(),c[157]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[158]||=i(` Oh that’s a nickname we were trying out.`,-1),c[159]||=a(`blockquote`,null,[a(`p`,null,`哦，那是我们试着取的绰号。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/040.mp3`}),c[160]||=i(),c[161]||=a(`strong`,null,`Ross Geller:`,-1),c[162]||=i(` Hey, y’know what nickname never caught on? The Ross-A-Tron! (Monica shakes her head in disgust.)`,-1),c[163]||=a(`blockquote`,null,[a(`p`,null,`嘿，你知道什么绰号从来没流行过吗？罗斯-阿-特隆！（莫妮卡厌恶地摇摇头。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/041.mp3`}),c[164]||=i(),c[165]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[166]||=i(` (entering) Hey!`,-1),c[167]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/042.mp3`}),c[168]||=i(),c[169]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[170]||=i(` Oh! Here’s Joseph Francis!`,-1),c[171]||=a(`blockquote`,null,[a(`p`,null,`哦！这是约瑟夫·弗朗西斯！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/043.mp3`}),c[172]||=i(),c[173]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[174]||=i(` Oh-Wha-Ho! What are you middle naming me for?! I left you a note!`,-1),c[175]||=a(`blockquote`,null,[a(`p`,null,`哦，哇哦！你叫我什么名字？！我给你留了张便条！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/044.mp3`}),c[176]||=i(),c[177]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[178]||=i(` So what?! That doesn’t give you the right to ditch me!`,-1),c[179]||=a(`blockquote`,null,[a(`p`,null,`那又怎样？！你没有权利抛弃我！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/045.mp3`}),c[180]||=i(),c[181]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[182]||=i(` Hey, you can cancel plans with friends if there is the possibility for sex!`,-1),c[183]||=a(`blockquote`,null,[a(`p`,null,`嘿，如果有可能发生性关系的话，你可以取消和朋友的计划！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/046.mp3`}),c[184]||=i(),c[185]||=a(`strong`,null,`Ross Geller:`,-1),c[186]||=i(` Phoebe he’s right, that is the rule.`,-1),c[187]||=a(`blockquote`,null,[a(`p`,null,`菲比，他是对的，这是规则。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/047.mp3`}),c[188]||=i(),c[189]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[190]||=i(` I don’t accept this rule. When me make plans, I expect you to show up. Okay, I can’t just be a way to kill time ‘til you meet someone better! Y’know boyfriends and girlfriends come and go, but this (Motions that their friendship) is for life!`,-1),c[191]||=a(`blockquote`,null,[a(`p`,null,`我不接受这个规则。当我制定计划时，我希望你能出现。好吧，在你遇到更好的人之前，我不能只是一种消磨时间的方式！你知道男朋友和女朋友来来往往，但这（表明他们的友谊）是终身的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/048.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[194]||=i(` Wow! I’m so sorry; I had no idea it would bother you this much.`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`哇！我很抱歉；我不知道这会让你这么烦恼。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/049.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[198]||=i(` Well, it does.`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/050.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[202]||=i(` Okay, can I-can I make it up to you? Huh? I’m sorry. (They hug.) How about uh, dinner tomorrow night?! I’ll pay for myself!`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`好吧，我能补偿你吗？嗯？我很抱歉。（他们拥抱）明天晚上吃晚饭怎么样？！我会自己付钱的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/051.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[206]||=i(` Okay, you wore me down.`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`好吧，你把我累坏了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/052.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Ross Geller:`,-1),c[210]||=i(` Hey Joe, while you’re over there how about another beer for the Ross-A-Tron?`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔，当你在那里的时候，再来一杯罗斯-阿-特隆啤酒怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/053.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[214]||=i(` The Ross—Is that back?!! (Chandler motions no.)`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`那个罗斯回来了？！！（钱德勒动议编号）`)],-1),c[216]||=a(`hr`,null,null,-1),c[217]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Chandler's, Rachel enters to find Chandler staring at another cheesecake box.`)],-1),c[218]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和钱德勒家，瑞秋进来发现钱德勒盯着另一个芝士蛋糕盒。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/054.mp3`}),c[219]||=i(),c[220]||=a(`strong`,null,`Rachel Green:`,-1),c[221]||=i(` Hi!`,-1),c[222]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/055.mp3`}),c[223]||=i(),c[224]||=a(`strong`,null,`Chandler Bing:`,-1),c[225]||=i(` Another cheesecake came! They delivered it to the wrong address again!`,-1),c[226]||=a(`blockquote`,null,[a(`p`,null,`又来了一块芝士蛋糕！他们又把它送到错误的地址了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/056.mp3`}),c[227]||=i(),c[228]||=a(`strong`,null,`Rachel Green:`,-1),c[229]||=i(` So just bring it back downstairs, what’s the problem?`,-1),c[230]||=a(`blockquote`,null,[a(`p`,null,`那就把它带下楼去，有什么问题吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/057.mp3`}),c[231]||=i(),c[232]||=a(`strong`,null,`Chandler Bing:`,-1),c[233]||=i(` I can’t seem to say goodbye.`,-1),c[234]||=a(`blockquote`,null,[a(`p`,null,`我好像不能说再见。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/058.mp3`}),c[235]||=i(),c[236]||=a(`strong`,null,`Rachel Green:`,-1),c[237]||=i(` Are you serious?! Chandler, we ate an entire cheesecake two days ago and you want more?`,-1),c[238]||=a(`blockquote`,null,[a(`p`,null,`你是认真的吗？！钱德勒，两天前我们吃了一整块芝士蛋糕，你还要吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/059.mp3`}),c[239]||=i(),c[240]||=a(`strong`,null,`Chandler Bing:`,-1),c[241]||=i(` Well I’ve forgotten what it tastes like okay?!`,-1),c[242]||=a(`blockquote`,null,[a(`p`,null,`我忘了它是什么味道了，好吗？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/060.mp3`}),c[243]||=i(),c[244]||=a(`strong`,null,`Rachel Green:`,-1),c[245]||=i(` It was cheesecake. It was fine. It had a buttery, crumbly, graham cracker crust, with a very rich yet light, cream cheese filling… (Pause) Wow! My whole mouth just filled with saliva!`,-1),c[246]||=a(`blockquote`,null,[a(`p`,null,`是芝士蛋糕。很好。它有一个奶油状的，易碎的，格雷厄姆饼干外壳，里面有一个非常丰富但很轻的奶油奶酪填充物…（停顿）哇！我满嘴都是唾液！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/061.mp3`}),c[247]||=i(),c[248]||=a(`strong`,null,`Chandler Bing:`,-1),c[249]||=i(` (closing the box) Y’know what? Forget it! We are just hungry! We have not had lunch! We are just light-headed! So let us go out and have lunch and forget about the cheesecake.`,-1),c[250]||=a(`blockquote`,null,[a(`p`,null,`（合上盒子）你知道吗？算了吧！我们只是饿了！我们还没吃午饭！我们只是头晕！所以，让我们出去吃午饭，忘掉芝士蛋糕吧。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/062.mp3`}),c[251]||=i(),c[252]||=a(`strong`,null,`Rachel Green:`,-1),c[253]||=i(` Yeah and we’ll drop it off downstairs so that we’re not tempted.`,-1),c[254]||=a(`blockquote`,null,[a(`p`,null,`是的，我们会把它放在楼下，这样我们就不会被诱惑了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/063.mp3`}),c[255]||=i(),c[256]||=a(`strong`,null,`Chandler Bing:`,-1),c[257]||=i(` Good idea. Where do you want to go to lunch?`,-1),c[258]||=a(`blockquote`,null,[a(`p`,null,`好主意。你想去哪里吃午饭？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/064.mp3`}),c[259]||=i(),c[260]||=a(`strong`,null,`Rachel Green:`,-1),c[261]||=i(` Momma’s Little Bakery, Chicago, Illinois. (They exit with the cheesecake.)`,-1),c[262]||=a(`blockquote`,null,[a(`p`,null,`妈妈的小面包店，伊利诺斯州芝加哥。（他们带着奶酪蛋糕离开。）`)],-1),c[263]||=a(`hr`,null,null,-1),c[264]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Monica and Joey are there. Joey is reading a newspaper.`)],-1),c[265]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，莫妮卡和乔伊在那里。乔伊正在看报纸。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/065.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[268]||=i(` Awww! Mel Torme died.`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`啊！梅尔·托姆死了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/066.mp3`}),c[270]||=i(),c[271]||=a(`strong`,null,`Monica Geller:`,-1),c[272]||=i(` Joey, that paper’s like a year old!`,-1),c[273]||=a(`blockquote`,null,[a(`p`,null,`乔伊，那家报纸有一年了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/067.mp3`}),c[274]||=i(),c[275]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[276]||=i(` Aw! Does that mean the Sam Goody’s sale is over?!`,-1),c[277]||=a(`blockquote`,null,[a(`p`,null,`噢！那是不是意味着山姆糖果的销售结束了？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/068.mp3`}),c[278]||=i(),c[279]||=a(`strong`,null,`Ross Geller:`,-1),c[280]||=i(` (entering) Hey.`,-1),c[281]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/069.mp3`}),c[282]||=i(),c[283]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[284]||=i(` Hey.`,-1),c[285]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/070.mp3`}),c[286]||=i(),c[287]||=a(`strong`,null,`Monica Geller:`,-1),c[288]||=i(` Hey.`,-1),c[289]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/071.mp3`}),c[290]||=i(),c[291]||=a(`strong`,null,`Ross Geller:`,-1),c[292]||=i(` So I finally heard back from Aunt Sheryl and apparently it wasn’t a mistake. Ahh, there’s-there’s limited seating in the hall.`,-1),c[293]||=a(`blockquote`,null,[a(`p`,null,`所以我终于收到了谢丽尔阿姨的回信，显然这不是一个错误。啊，大厅里的座位有限。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/072.mp3`}),c[294]||=i(),c[295]||=a(`strong`,null,`Monica Geller:`,-1),c[296]||=i(` Limited seating?! (Screechingly) I am just one tiny person!`,-1),c[297]||=a(`blockquote`,null,[a(`p`,null,`座位有限？！（尖叫）我只是一个小小的人！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/073.mp3`}),c[298]||=i(),c[299]||=a(`strong`,null,`Ross Geller:`,-1),c[300]||=i(` Well yeah, but she doesn’t know that. I mean, the last time she saw you-you would’ve turned one of those little wedding chairs into kindling.`,-1),c[301]||=a(`blockquote`,null,[a(`p`,null,`是的，但她不知道。我是说，她最后一次见到你的时候，你会把一把婚礼用的小椅子变成火柴。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/074.mp3`}),c[302]||=i(),c[303]||=a(`strong`,null,`Monica Geller:`,-1),c[304]||=i(` (disgusted) Limited seating! Oh, that is such a lame excuse! That’s not the reason she’s not inviting me!`,-1),c[305]||=a(`blockquote`,null,[a(`p`,null,`（恶心）座位有限！哦，这是一个多么站不住脚的借口！这不是她不邀请我的原因！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/075.mp3`}),c[306]||=i(),c[307]||=a(`strong`,null,`Ross Geller:`,-1),c[308]||=i(` Oh what’s the big deal?! I wasn’t even invited to the ceremony, just the reception. And-and y’know what? If it makes you feel any better, Joan and I will just make an appearance and then, and then we’ll-we’ll leave early as a sign of protest.`,-1),c[309]||=a(`blockquote`,null,[a(`p`,null,`哦，有什么大不了的？！我甚至没有被邀请参加典礼，只是参加招待会。你知道吗？如果这能让你感觉好一点，琼和我会先露面，然后，我们会——我们会早点离开，以示抗议。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/076.mp3`}),c[310]||=i(),c[311]||=a(`strong`,null,`Monica Geller:`,-1),c[312]||=i(` Joan?`,-1),c[313]||=a(`blockquote`,null,[a(`p`,null,`琼？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/077.mp3`}),c[314]||=i(),c[315]||=a(`strong`,null,`Ross Geller:`,-1),c[316]||=i(` Yeah, Joan Tedeski my date. She’s an assistant professor in the Linguistics department. Tall, very beautiful, and despite what some people say, not broad backed!`,-1),c[317]||=a(`blockquote`,null,[a(`p`,null,`是的，琼·特德斯基是我的约会对象。她是语言学系的助理教授。高高的，非常漂亮，尽管有些人说，不是宽背！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/078.mp3`}),c[318]||=i(),c[319]||=a(`strong`,null,`Monica Geller:`,-1),c[320]||=i(` Wait a minute, you got Ross Gellar and guest?! I wasn’t invited and you got "and guest?!"`,-1),c[321]||=a(`blockquote`,null,[a(`p`,null,`等等，你有罗斯·盖勒和客人吗？！我没有被邀请，你却得到了“还有客人？！”`)],-1),r(p,{src:`/audio/friends/S07/S07E11/079.mp3`}),c[322]||=i(),c[323]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[324]||=i(` Uh-uh, excuse me, I do have to interrupt on Ross’s behalf. I-I think the rule applies here y’know, since she has a chance to get on broad back…`,-1),c[325]||=a(`blockquote`,null,[a(`p`,null,`呃，对不起，我得代表罗斯打断一下。我-我认为规则适用于这里，你知道，因为她有机会得到广泛的支持…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/080.mp3`}),c[326]||=i(),c[327]||=a(`strong`,null,`Ross Geller:`,-1),c[328]||=i(` (interrupting) Not broad backed!`,-1),c[329]||=a(`blockquote`,null,[a(`p`,null,`（打断）不是宽背！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/081.mp3`}),c[330]||=i(),c[331]||=a(`strong`,null,`Monica Geller:`,-1),c[332]||=i(` Wait a minute, y’know, you’re bringing me!`,-1),c[333]||=a(`blockquote`,null,[a(`p`,null,`等一下，你知道，你要带我来！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/082.mp3`}),c[334]||=i(),c[335]||=a(`strong`,null,`Ross Geller:`,-1),c[336]||=i(` What? I can’t cancel on Joan!`,-1),c[337]||=a(`blockquote`,null,[a(`p`,null,`什么？我不能取消琼的约会！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/083.mp3`}),c[338]||=i(),c[339]||=a(`strong`,null,`Monica Geller:`,-1),c[340]||=i(` Why not?!`,-1),c[341]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/084.mp3`}),c[342]||=i(),c[343]||=a(`strong`,null,`Ross Geller:`,-1),c[344]||=i(` Bec—Did you not hear me?! She’s an assistant professor in the Linguistics department, okay? They’re wild! Why do you want to come anyway?`,-1),c[345]||=a(`blockquote`,null,[a(`p`,null,`你没听见我说话吗？！她是语言学系的助理教授，好吗？他们太野了！你到底为什么想来？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/085.mp3`}),c[346]||=i(),c[347]||=a(`strong`,null,`Monica Geller:`,-1),c[348]||=i(` Because! She’s my cousin. I mean, we grew up together! We’re family y’know? Well that’s important to me.`,-1),c[349]||=a(`blockquote`,null,[a(`p`,null,`因为！她是我表妹。我是说，我们是一起长大的！我们是一家人，你知道吗？这对我很重要。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/086.mp3`}),c[350]||=i(),c[351]||=a(`strong`,null,`Ross Geller:`,-1),c[352]||=i(` Okay, all right, I’ll take you. I’ll go call Joan. (Does so.)`,-1),c[353]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，我带你去。我去给琼打电话。（确实如此。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/087.mp3`}),c[354]||=i(),c[355]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[356]||=i(` Aww that’s nice. Family should be there, huh? This is her wedding, happiest day of her life.`,-1),c[357]||=a(`blockquote`,null,[a(`p`,null,`啊，那太好了。家人应该在那里，是吗？这是她的婚礼，她一生中最快乐的一天。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/088.mp3`}),c[358]||=i(),c[359]||=a(`strong`,null,`Monica Geller:`,-1),c[360]||=i(` (laughs) We’ll see.`,-1),c[361]||=a(`blockquote`,null,[a(`p`,null,`（笑）我们拭目以待。`)],-1),c[362]||=a(`hr`,null,null,-1),c[363]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Lobby of Chandler and Rachel’s building, Chandler and Rachel are returning from lunch.`)],-1),c[364]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和瑞秋的大楼大厅，钱德勒和瑞秋正在吃午饭回来。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/089.mp3`}),c[365]||=i(),c[366]||=a(`strong`,null,`Chandler Bing:`,-1),c[367]||=i(` Well, thank you for lunch.`,-1),c[368]||=a(`blockquote`,null,[a(`p`,null,`谢谢你的午餐。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/090.mp3`}),c[369]||=i(),c[370]||=a(`strong`,null,`Rachel Green:`,-1),c[371]||=i(` What? Wait a minute, I didn’t pay, I thought you paid!`,-1),c[372]||=a(`blockquote`,null,[a(`p`,null,`什么？等等，我没付钱，我以为你付钱了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/091.mp3`}),c[373]||=i(),c[374]||=a(`strong`,null,`Chandler Bing:`,-1),c[375]||=i(` So apparently we just don’t pay for food anymore. (Rachel laughs then Chandler notices something.) Do you see what I see?`,-1),c[376]||=a(`blockquote`,null,[a(`p`,null,`所以很明显我们不再付钱买食物了。（瑞秋笑了，钱德勒注意到了什么。）你看到我看到的了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/092.mp3`}),c[377]||=i(),c[378]||=a(`strong`,null,`Rachel Green:`,-1),c[379]||=i(` (gasps) Its still there! (The cheesecake they returned to Mrs. Braverman is still lying in front of her door.)`,-1),c[380]||=a(`blockquote`,null,[a(`p`,null,`（喘息）它还在那里！（他们还给布拉弗曼夫人的奶酪蛋糕仍然放在她的门前。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/093.mp3`}),c[381]||=i(),c[382]||=a(`strong`,null,`Chandler Bing:`,-1),c[383]||=i(` Mrs. Braverman must be out. (They move closer to it.)`,-1),c[384]||=a(`blockquote`,null,[a(`p`,null,`布雷弗曼夫人一定出去了。（他们向它靠近。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/094.mp3`}),c[385]||=i(),c[386]||=a(`strong`,null,`Rachel Green:`,-1),c[387]||=i(` She could be out of town. Maybe she’ll be gone for months.`,-1),c[388]||=a(`blockquote`,null,[a(`p`,null,`她可能出城了。也许她会离开几个月。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/095.mp3`}),c[389]||=i(),c[390]||=a(`strong`,null,`Chandler Bing:`,-1),c[391]||=i(` By then, the cheesecake may have gone bad. We don’t want her to come back to bad cheesecake.`,-1),c[392]||=a(`blockquote`,null,[a(`p`,null,`到那时，奶酪蛋糕可能已经坏了。我们不想让她回到坏奶酪蛋糕上来。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/096.mp3`}),c[393]||=i(),c[394]||=a(`strong`,null,`Rachel Green:`,-1),c[395]||=i(` No that could kill her.`,-1),c[396]||=a(`blockquote`,null,[a(`p`,null,`不，那会杀了她。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/097.mp3`}),c[397]||=i(),c[398]||=a(`strong`,null,`Chandler Bing:`,-1),c[399]||=i(` Well, we don’t want that.`,-1),c[400]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们不想那样。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/098.mp3`}),c[401]||=i(),c[402]||=a(`strong`,null,`Rachel Green:`,-1),c[403]||=i(` No so we’re protecting her.`,-1),c[404]||=a(`blockquote`,null,[a(`p`,null,`不，所以我们在保护她。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/099.mp3`}),c[405]||=i(),c[406]||=a(`strong`,null,`Chandler Bing:`,-1),c[407]||=i(` But we should take it.`,-1),c[408]||=a(`blockquote`,null,[a(`p`,null,`但我们应该接受它。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/100.mp3`}),c[409]||=i(),c[410]||=a(`strong`,null,`Rachel Green:`,-1),c[411]||=i(` But we should move quick.`,-1),c[412]||=a(`blockquote`,null,[a(`p`,null,`但我们应该快点行动。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/101.mp3`}),c[413]||=i(),c[414]||=a(`strong`,null,`Chandler Bing:`,-1),c[415]||=i(` Why?`,-1),c[416]||=a(`blockquote`,null,[a(`p`,null,`为什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/102.mp3`}),c[417]||=i(),c[418]||=a(`strong`,null,`Rachel Green:`,-1),c[419]||=i(` Because I think I just heard her moving around in there.`,-1),c[420]||=a(`blockquote`,null,[a(`p`,null,`因为我想我刚听到她在里面走动。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/103.mp3`}),c[421]||=i(),c[422]||=a(`strong`,null,`Chandler Bing:`,-1),c[423]||=i(` Go! Go! Go! Go! Go! Go! Go! Go! Go! Go! (Rachel grabs the cheesecake and they take off upstairs.)`,-1),c[424]||=a(`blockquote`,null,[a(`p`,null,`走！走！走！走！走！走！走！走！走！走！（瑞秋抓起奶酪蛋糕，他们上楼了。）`)],-1),c[425]||=a(`hr`,null,null,-1),c[426]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Monica and Phoebe are entering. As Phoebe is sitting down, she recognizes someone sitting at the counter.`)],-1),c[427]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，莫妮卡和菲比进入。菲比坐下时，她认出有人坐在柜台旁。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/104.mp3`}),c[428]||=i(),c[429]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[430]||=i(` (gasps) (whispering) Oh my God! That’s David!`,-1),c[431]||=a(`blockquote`,null,[a(`p`,null,`（喘息）（耳语）哦，我的天啊！那是大卫！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/105.mp3`}),c[432]||=i(),c[433]||=a(`strong`,null,`Monica Geller:`,-1),c[434]||=i(` David who?`,-1),c[435]||=a(`blockquote`,null,[a(`p`,null,`大卫，谁？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/106.mp3`}),c[436]||=i(),c[437]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[438]||=i(` David the scientist guy, David that I was in love with, David who went to Russia and broke my heart David!`,-1),c[439]||=a(`blockquote`,null,[a(`p`,null,`科学家大卫，我爱的大卫，去俄罗斯伤了我心的大卫，大卫！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/107.mp3`}),c[440]||=i(),c[441]||=a(`strong`,null,`David:`,-1),c[442]||=i(` (noticing Phoebe) Oh my God!`,-1),c[443]||=a(`blockquote`,null,[a(`p`,null,`（注意到菲比）哦，天哪！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/108.mp3`}),c[444]||=i(),c[445]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[446]||=i(` Oh, you say someone’s name enough, they turn around.`,-1),c[447]||=a(`blockquote`,null,[a(`p`,null,`哦，你说某人的名字够多了，他们就会转过身来。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/109.mp3`}),c[448]||=i(),c[449]||=a(`strong`,null,`David:`,-1),c[450]||=i(` Phoebe?`,-1),c[451]||=a(`blockquote`,null,[a(`p`,null,`菲比？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/110.mp3`}),c[452]||=i(),c[453]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[454]||=i(` David! (He kisses her cheek) What-what are you doing here? Aren’t you supposed to be in Russia?`,-1),c[455]||=a(`blockquote`,null,[a(`p`,null,`大卫！（他吻了吻她的脸颊）你在这里干什么？你不是应该在俄罗斯吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/111.mp3`}),c[456]||=i(),c[457]||=a(`strong`,null,`David:`,-1),c[458]||=i(` Yeah, I’m just, I’m just in town for a conference. Umm, God you look phenomenal!`,-1),c[459]||=a(`blockquote`,null,[a(`p`,null,`是的，我只是，我只是来参加一个会议。哦，天哪，你看起来真了不起！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/112.mp3`}),c[460]||=i(),c[461]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[462]||=i(` Well… Yeah. You look great too. Did you get a haircut?`,-1),c[463]||=a(`blockquote`,null,[a(`p`,null,`嗯……是的。你看起来也很棒。你理发了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/113.mp3`}),c[464]||=i(),c[465]||=a(`strong`,null,`David:`,-1),c[466]||=i(` Yeah. Well I-I got like thirty of them.`,-1),c[467]||=a(`blockquote`,null,[a(`p`,null,`是的。嗯，我——我大概有三十个。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/114.mp3`}),c[468]||=i(),c[469]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[470]||=i(` Yeah.`,-1),c[471]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/115.mp3`}),c[472]||=i(),c[473]||=a(`strong`,null,`David:`,-1),c[474]||=i(` Umm, look I-I-I got a confession to make…`,-1),c[475]||=a(`blockquote`,null,[a(`p`,null,`嗯，听着，我-我-我要坦白…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/116.mp3`}),c[476]||=i(),c[477]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[478]||=i(` Uh-huh.`,-1),c[479]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/117.mp3`}),c[480]||=i(),c[481]||=a(`strong`,null,`David:`,-1),c[482]||=i(` Uh, I-I-I was hoping to run into you here. I didn’t know whether I should call or not, y’know I-I was only in town for a few days. And y’know, I didn’t want to intrude on your life or-or anything like that, but I-I really wanted to see you and—but I didn’t know if you wanted to see me.`,-1),c[483]||=a(`blockquote`,null,[a(`p`,null,`呃，我-我-我希望在这里碰到你。我不知道该不该打电话，你知道我只是在城里呆了几天。你知道，我不想打扰你的生活或诸如此类的事情，但我真的很想见你，但我不知道你是否想见我。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/118.mp3`}),c[484]||=i(),c[485]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[486]||=i(` Well, of course I would want to see you. I…I think about you all the time.`,-1),c[487]||=a(`blockquote`,null,[a(`p`,null,`嗯，我当然想见你。我…我一直在想你。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/119.mp3`}),c[488]||=i(),c[489]||=a(`strong`,null,`David:`,-1),c[490]||=i(` Really? Because I think about you all the time.`,-1),c[491]||=a(`blockquote`,null,[a(`p`,null,`真的吗？因为我一直在想你。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/120.mp3`}),c[492]||=i(),c[493]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[494]||=i(` Really?`,-1),c[495]||=a(`blockquote`,null,[a(`p`,null,`真的吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/121.mp3`}),c[496]||=i(),c[497]||=a(`strong`,null,`David:`,-1),c[498]||=i(` I mean, there’s a statue in Minsk…`,-1),c[499]||=a(`blockquote`,null,[a(`p`,null,`我是说，明斯克有一座雕像…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/122.mp3`}),c[500]||=i(),c[501]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[502]||=i(` Uh-huh.`,-1),c[503]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/123.mp3`}),c[504]||=i(),c[505]||=a(`strong`,null,`David:`,-1),c[506]||=i(` That reminds me of you so much, I mean umm, it-it’s actually of Lenin. But, y’know at certain angles…`,-1),c[507]||=a(`blockquote`,null,[a(`p`,null,`这让我想起了你，我是说，嗯，实际上是列宁。但是，你知道在某些角度上…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/124.mp3`}),c[508]||=i(),c[509]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[510]||=i(` Yeah.`,-1),c[511]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/125.mp3`}),c[512]||=i(),c[513]||=a(`strong`,null,`David:`,-1),c[514]||=i(` Umm, anyway…Do you want to have dinner tonight?`,-1),c[515]||=a(`blockquote`,null,[a(`p`,null,`嗯，不管怎样……你今晚想吃饭吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/126.mp3`}),c[516]||=i(),c[517]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[518]||=i(` (excited) Yes! Oh no!`,-1),c[519]||=a(`blockquote`,null,[a(`p`,null,`（兴奋）是的！哦，不！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/127.mp3`}),c[520]||=i(),c[521]||=a(`strong`,null,`David:`,-1),c[522]||=i(` (disappointed) Oh. Uh, what?`,-1),c[523]||=a(`blockquote`,null,[a(`p`,null,`（失望）哦。嗯，什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/128.mp3`}),c[524]||=i(),c[525]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[526]||=i(` I can’t. I can’t believe I have plans, I can’t. Can you do it tomorrow night though?`,-1),c[527]||=a(`blockquote`,null,[a(`p`,null,`我不能。我不敢相信我有计划，我没有。明天晚上你能做吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/129.mp3`}),c[528]||=i(),c[529]||=a(`strong`,null,`David:`,-1),c[530]||=i(` Uh no, I have to go in a few hours. I have to be on the red-eye. Well listen, y’know, next time you’re in Minsk umm…`,-1),c[531]||=a(`blockquote`,null,[a(`p`,null,`不，我几个小时后就得走了。我必须红眼睛。听着，你知道，下次你在明斯克的时候…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/130.mp3`}),c[532]||=i(),c[533]||=a(`strong`,null,`Monica Geller:`,-1),c[534]||=i(` Phoebe, can I talk to you for a second?`,-1),c[535]||=a(`blockquote`,null,[a(`p`,null,`菲比，我能和你谈谈吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/131.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[538]||=i(` Uh-huh. (They go over and talk.)`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`嗯。（他们走过去交谈。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/132.mp3`}),c[540]||=i(),c[541]||=a(`strong`,null,`Monica Geller:`,-1),c[542]||=i(` What are you doing?`,-1),c[543]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/133.mp3`}),c[544]||=i(),c[545]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[546]||=i(` Well, I have plans with Joey tonight.`,-1),c[547]||=a(`blockquote`,null,[a(`p`,null,`嗯，我今晚和乔伊有安排。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/134.mp3`}),c[548]||=i(),c[549]||=a(`strong`,null,`Monica Geller:`,-1),c[550]||=i(` So! He’ll understand!`,-1),c[551]||=a(`blockquote`,null,[a(`p`,null,`那么！他会理解的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/135.mp3`}),c[552]||=i(),c[553]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[554]||=i(` No he won’t. And that’s not even the point! Monica, I made a whole speech about you do not cancel plans with friends! And now y’know what? Just because, potentially, the love of my life comes back from Russia just for one night, I-I should change my beliefs?! I should change beliefs! No! No! No, if I don’t have my principles, I don’t have anything!`,-1),c[555]||=a(`blockquote`,null,[a(`p`,null,`不，他不会的。这甚至不是重点！莫妮卡，我做了一个关于你不要取消和朋友的计划的演讲！现在你知道了吗？就因为，可能，我一生的挚爱只从俄罗斯回来一晚，我——我应该改变我的信仰？！我应该改变信仰！不不不，如果我没有原则，我什么都没有！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/136.mp3`}),c[556]||=i(),c[557]||=a(`strong`,null,`Monica Geller:`,-1),c[558]||=i(` God, you are so strong.`,-1),c[559]||=a(`blockquote`,null,[a(`p`,null,`天啊，你真强壮。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/137.mp3`}),c[560]||=t(` <strong>Phoebe Buffay:</strong> Or! I should rush through dinner with Joey and I can meet David at 9:00!<blockquote><p>或者！我应该赶紧和乔伊一起吃晚饭，我可以在9点见大卫！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Joey and Rachel&#39;s, Rachel and Chandler are eating the cheesecake right out of the box.</em></p><blockquote><p>🎬 <em>乔伊和瑞秋家，瑞秋和钱德勒正在吃盒子里的奶酪蛋糕。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E11/138.mp3`}),c[561]||=i(),c[562]||=a(`strong`,null,`Rachel Green:`,-1),c[563]||=i(` (taking a bite) Oh my God! That is so good!`,-1),c[564]||=a(`blockquote`,null,[a(`p`,null,`（咬了一口）哦，我的天啊！太好了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/139.mp3`}),c[565]||=i(),c[566]||=a(`strong`,null,`Chandler Bing:`,-1),c[567]||=i(` I’m full, and yet I know if I stop eating this, I’ll regret it.`,-1),c[568]||=a(`blockquote`,null,[a(`p`,null,`我吃饱了，但我知道如果我不吃这个，我会后悔的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/140.mp3`}),c[569]||=i(),c[570]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[571]||=i(` (entering) Hey!`,-1),c[572]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/141.mp3`}),c[573]||=i(),c[574]||=a(`strong`,null,`Rachel Green:`,-1),c[575]||=i(` Hey!`,-1),c[576]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/142.mp3`}),c[577]||=i(),c[578]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[579]||=i(` (seeing what they’re doing) What do you got there?`,-1),c[580]||=a(`blockquote`,null,[a(`p`,null,`（看到他们在做什么）你有什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/143.mp3`}),c[581]||=i(),c[582]||=a(`strong`,null,`Rachel Green:`,-1),c[583]||=i(` Oh it’s umm, it’s tofu cake. Do you want some? (He makes a disgusted noise and heads for his room, Chandler follows him in.)`,-1),c[584]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯，是豆腐蛋糕。你想要一些吗？（他发出令人厌恶的声音，朝他的房间走去，钱德勒跟着他进来。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/144.mp3`}),c[585]||=i(),c[586]||=a(`strong`,null,`Chandler Bing:`,-1),c[587]||=i(` What are you doing tonight?`,-1),c[588]||=a(`blockquote`,null,[a(`p`,null,`你今晚要干什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/145.mp3`}),c[589]||=i(),c[590]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[591]||=i(` Huh? Uh… (He starts taking off his pants.)`,-1),c[592]||=a(`blockquote`,null,[a(`p`,null,`嗯？嗯…（他开始脱裤子。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/146.mp3`}),c[593]||=i(),c[594]||=a(`strong`,null,`Chandler Bing:`,-1),c[595]||=i(` Dude! Dude! (Motions that Joey should pull up his pants.)`,-1),c[596]||=a(`blockquote`,null,[a(`p`,null,`老兄！伙计！（乔伊应该拉起裤子的动作。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/147.mp3`}),c[597]||=i(),c[598]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[599]||=i(` Oh! (Pulls up his pants.) Sorry. Uh, I’ve got those plans with Phoebe, why?`,-1),c[600]||=a(`blockquote`,null,[a(`p`,null,`哦！（拉起裤子）对不起。呃，我和菲比有那些计划，为什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/148.mp3`}),c[601]||=i(),c[602]||=a(`strong`,null,`Chandler Bing:`,-1),c[603]||=i(` Oh really? Uh, Monica said she had a date at 9:00.`,-1),c[604]||=a(`blockquote`,null,[a(`p`,null,`哦，真的吗？莫妮卡说她9点有个约会。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/149.mp3`}),c[605]||=i(),c[606]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[607]||=i(` What?! Tonight?!`,-1),c[608]||=a(`blockquote`,null,[a(`p`,null,`什么？！今晚`)],-1),r(p,{src:`/audio/friends/S07/S07E11/150.mp3`}),c[609]||=i(),c[610]||=a(`strong`,null,`Chandler Bing:`,-1),c[611]||=i(` That’s what Monica said.`,-1),c[612]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡就是这么说的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/151.mp3`}),c[613]||=i(),c[614]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[615]||=i(` After she gave me that big speech?! She goes and makes a date with a guy on the same night she has plans with me? I think she’s trying to pull a fast one on Big Daddy!`,-1),c[616]||=a(`blockquote`,null,[a(`p`,null,`在她给我做了那个重要的演讲之后？！她和我有约会的那天晚上就去和一个男人约会了？我想她是想对大爸爸耍花招！`)],-1),c[617]||=a(`hr`,null,null,-1),c[618]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Cousin Frannie’s Wedding Reception, Monica and Ross are entering and finding their table.`)],-1),c[619]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`表哥弗兰妮的婚礼招待会，莫妮卡和罗斯走进来找他们的桌子。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/152.mp3`}),c[620]||=i(),c[621]||=a(`strong`,null,`Ross Geller:`,-1),c[622]||=i(` Oh here, I think this is us. (Reading the name cards.) Yeah.`,-1),c[623]||=a(`blockquote`,null,[a(`p`,null,`哦，这里，我想这是我们。（读名片）是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/153.mp3`}),c[624]||=i(),c[625]||=a(`strong`,null,`Monica Geller:`,-1),c[626]||=i(` Limited seating my ass. Let’s see who made the cut. (To the couple sitting to her right.) Hi!`,-1),c[627]||=a(`blockquote`,null,[a(`p`,null,`我的屁股有限。让我们看看是谁切的。（对坐在她右边的那对夫妇）嗨！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/154.mp3`}),c[628]||=i(),c[629]||=a(`strong`,null,`The Wedding Guest:`,-1),c[630]||=i(` Hi!`,-1),c[631]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/155.mp3`}),c[632]||=i(),c[633]||=a(`strong`,null,`Monica Geller:`,-1),c[634]||=i(` I’m Monica Gellar. Who do you know the bride and groom?`,-1),c[635]||=a(`blockquote`,null,[a(`p`,null,`我是莫妮卡·盖拉。你认识新娘和新郎吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/156.mp3`}),c[636]||=i(),c[637]||=a(`strong`,null,`The Wedding Guest:`,-1),c[638]||=i(` Oh, I used to work with Frannie.`,-1),c[639]||=a(`blockquote`,null,[a(`p`,null,`哦，我以前和弗兰妮一起工作。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/157.mp3`}),c[640]||=i(),c[641]||=a(`strong`,null,`Monica Geller:`,-1),c[642]||=i(` Used to work with her. Used to! I’m a relative and I didn’t get invited! A blood relative! Blood!!`,-1),c[643]||=a(`blockquote`,null,[a(`p`,null,`以前和她一起工作过。曾经我是亲戚，没有被邀请！血亲！血！！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/158.mp3`}),c[644]||=i(),c[645]||=a(`strong`,null,`Ross Geller:`,-1),c[646]||=i(` (To Monica) Stop saying, "Blood" to strangers.`,-1),c[647]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）别对陌生人说“血”。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/159.mp3`}),c[648]||=i(),c[649]||=a(`strong`,null,`Monica Geller:`,-1),c[650]||=i(` (to the couple on her left) So, how about you huh? How do you know the happy couple?`,-1),c[651]||=a(`blockquote`,null,[a(`p`,null,`（对她左边的那对夫妇）那么，你呢？你是怎么认识这对幸福的夫妇的？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/160.mp3`}),c[652]||=i(),c[653]||=a(`strong`,null,`The Second Guest:`,-1),c[654]||=i(` We went to college with both of them and now we live next door.`,-1),c[655]||=a(`blockquote`,null,[a(`p`,null,`我们和他们一起上大学，现在我们住在隔壁。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/161.mp3`}),c[656]||=i(),c[657]||=a(`strong`,null,`Monica Geller:`,-1),c[658]||=i(` Okay, you’re fine.`,-1),c[659]||=a(`blockquote`,null,[a(`p`,null,`好的，你很好。`)],-1),c[660]||=a(`hr`,null,null,-1),c[661]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Iridium Restaurant, Phoebe and Joey are looking at the menus as the waiter comes to take their order.`)],-1),c[662]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`铱星餐厅，当服务员过来点菜时，菲比和乔伊正在看菜单。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/162.mp3`}),c[663]||=i(),c[664]||=a(`strong`,null,`The Waiter:`,-1),c[665]||=i(` Hey!`,-1),c[666]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/163.mp3`}),c[667]||=i(),c[668]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[669]||=i(` Hey!`,-1),c[670]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/164.mp3`}),c[671]||=i(),c[672]||=a(`strong`,null,`The Waiter:`,-1),c[673]||=i(` Are you guys ready?`,-1),c[674]||=a(`blockquote`,null,[a(`p`,null,`你们准备好了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/165.mp3`}),c[675]||=i(),c[676]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[677]||=i(` Yes! I will have the green salad, umm the house salad, and water’s fine.`,-1),c[678]||=a(`blockquote`,null,[a(`p`,null,`是的！我要蔬菜沙拉，嗯，家庭沙拉，还有水。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/166.mp3`}),c[679]||=i(),c[680]||=a(`strong`,null,`The Waiter:`,-1),c[681]||=i(` Okay.`,-1),c[682]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/167.mp3`}),c[683]||=i(),c[684]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[685]||=i(` Okay.`,-1),c[686]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/168.mp3`}),c[687]||=i(),c[688]||=a(`strong`,null,`The Waiter:`,-1),c[689]||=i(` (To Joey) And for you sir?`,-1),c[690]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）先生，你呢？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/169.mp3`}),c[691]||=i(),c[692]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[693]||=i(` Yeah, this slow roasted salmon, just how slow are we talkin’ here?`,-1),c[694]||=a(`blockquote`,null,[a(`p`,null,`是啊，这个慢烤鲑鱼，我们在这里说话有多慢？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/170.mp3`}),c[695]||=i(),c[696]||=a(`strong`,null,`The Waiter:`,-1),c[697]||=i(` It’s uh, it’s already been roasted.`,-1),c[698]||=a(`blockquote`,null,[a(`p`,null,`嗯，已经烤过了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/171.mp3`}),c[699]||=i(),c[700]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[701]||=i(` Ohh, then no. Maybe I should hear those specials again.`,-1),c[702]||=a(`blockquote`,null,[a(`p`,null,`哦，那就不要了。也许我应该再听一遍那些特色菜。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/172.mp3`}),c[703]||=i(),c[704]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[705]||=i(` Oh Joey, we’ve heard the specials three times! Okay? There’s prime rib, mahi mahi, and a very special lobster ravioli. (She grabs his menu and hands it to the waiter.)`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,`哦，乔伊，我们已经听过三次特价了！可以有上好的肋骨，麻辣麻辣，还有一种非常特别的龙虾水饺。（她抓起他的菜单递给服务员。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/173.mp3`}),c[707]||=i(),c[708]||=a(`strong`,null,`The Waiter:`,-1),c[709]||=i(` Actually we’re out of the lobster ravioli. (Putting Joey’s menu under his arm.)`,-1),c[710]||=a(`blockquote`,null,[a(`p`,null,`事实上，龙虾馄饨已经卖完了。（把乔伊的菜单放在他的胳膊下。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/174.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[713]||=i(` Oh well, that changes everything! (Grabs his menu and starts looking at it again. The waiter leaves.) Y’know what Pheebs?`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`哦，那改变了一切！（抓起菜单又看了一遍。服务员离开了。）你知道什么是菲比吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/175.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[717]||=i(` Huh?`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`嗯？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/176.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[721]||=i(` You were right before. I mean, friends are so important.`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`你以前是对的。我是说，朋友很重要。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/177.mp3`}),c[723]||=i(),c[724]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[725]||=i(` (checking her watch) Yeah, I’m very wise. I know.`,-1),c[726]||=a(`blockquote`,null,[a(`p`,null,`（看手表）是的，我很聪明。我知道。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/178.mp3`}),c[727]||=i(),c[728]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[729]||=i(` Y’know-y’know what I really want?`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,`你知道我真正想要什么吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/179.mp3`}),c[731]||=i(),c[732]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[733]||=i(` What?`,-1),c[734]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/180.mp3`}),c[735]||=i(),c[736]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[737]||=i(` Is to have a long, long talk. Y’know? Get Joey out on the open road and really open him up.`,-1),c[738]||=a(`blockquote`,null,[a(`p`,null,`就是要有一个很长很长的谈话。你知道吗？把乔伊带到开阔的路上，让他敞开心扉。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/181.mp3`}),c[739]||=i(),c[740]||=a(`strong`,null,`The Waiter:`,-1),c[741]||=i(` (returning) Any progress?`,-1),c[742]||=a(`blockquote`,null,[a(`p`,null,`（回答）有什么进展吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/182.mp3`}),c[743]||=i(),c[744]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[745]||=i(` Yes! I will have the lobster ravioli.`,-1),c[746]||=a(`blockquote`,null,[a(`p`,null,`是的！我要龙虾水饺。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/183.mp3`}),c[747]||=i(),c[748]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[749]||=i(` God Joey, this is taking forever!`,-1),c[750]||=a(`blockquote`,null,[a(`p`,null,`天哪，乔伊，这太费时了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/184.mp3`}),c[751]||=i(),c[752]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[753]||=i(` What’s the rush? What?`,-1),c[754]||=a(`blockquote`,null,[a(`p`,null,`你急什么？什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/185.mp3`}),c[755]||=i(),c[756]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[757]||=i(` W-w—I just—it’s that—I have—y’know I have-I have an appointment. And it’s very important.`,-1),c[758]||=a(`blockquote`,null,[a(`p`,null,`我只是，我知道我有个约会。这非常重要。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/186.mp3`}),c[759]||=i(),c[760]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[761]||=i(` Whoa-whoa, what is it?`,-1),c[762]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，是什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/187.mp3`}),c[763]||=i(),c[764]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[765]||=i(` Well… It’s a date.`,-1),c[766]||=a(`blockquote`,null,[a(`p`,null,`嗯……这是约会。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/188.mp3`}),c[767]||=i(),c[768]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[769]||=i(` A date?! No, no Pheebs you-you must be mistaken, because I know you wouldn’t schedule a date on the same night you have plans with a friend!`,-1),c[770]||=a(`blockquote`,null,[a(`p`,null,`约会？！不，不，菲比，你一定弄错了，因为我知道你不会在你和朋友计划的同一天晚上约会！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/189.mp3`}),c[771]||=i(),c[772]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[773]||=i(` Come on Joey, don’t make me feel badly about this.`,-1),c[774]||=a(`blockquote`,null,[a(`p`,null,`来吧，乔伊，别让我为此感到难过。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/190.mp3`}),c[775]||=i(),c[776]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[777]||=i(` No, I’m gonna!! That’s right! Yeah, you made me feel really guilty about goin’ out with that girl! Like-like-like I did something terrible to you! And now Pheebs, you’re doing the same thing!`,-1),c[778]||=a(`blockquote`,null,[a(`p`,null,`不，我要去！！这是正确的！是的，你让我对和那个女孩约会感到内疚！好像我对你做了什么可怕的事！现在菲比，你也在做同样的事情！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/191.mp3`}),c[779]||=i(),c[780]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[781]||=i(` That—It’s not the same thing! This is totally different! This is with David! Remember David, the scientist guy? Okay, he’s very special to me.`,-1),c[782]||=a(`blockquote`,null,[a(`p`,null,`那不是一回事！这完全不同！这是大卫的！还记得科学家大卫吗？好吧，他对我来说很特别。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/192.mp3`}),c[783]||=i(),c[784]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[785]||=i(` Okay, well my girl from the other night was special. She was a scientist too!`,-1),c[786]||=a(`blockquote`,null,[a(`p`,null,`好吧，那天晚上我的女朋友很特别。她也是科学家！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/193.mp3`}),c[787]||=i(),c[788]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[789]||=i(` She was?`,-1),c[790]||=a(`blockquote`,null,[a(`p`,null,`她是？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/194.mp3`}),c[791]||=i(),c[792]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[793]||=i(` Well, she graduated from high school!`,-1),c[794]||=a(`blockquote`,null,[a(`p`,null,`嗯，她高中毕业了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/195.mp3`}),c[795]||=i(),c[796]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[797]||=i(` Okay, whatever. Y’know what? I don’t have time have time to convince you because he’s only here for four hours, and I’m gonna go see him! (Gets up and leaves.)`,-1),c[798]||=a(`blockquote`,null,[a(`p`,null,`好吧，随便吧。你知道吗？我没时间说服你，因为他只在这里呆了四个小时，我要去见他！（起身离开。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/196.mp3`}),c[799]||=i(),c[800]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[801]||=i(` Fine!`,-1),c[802]||=a(`blockquote`,null,[a(`p`,null,`很好！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/197.mp3`}),c[803]||=i(),c[804]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[805]||=i(` Yeah!`,-1),c[806]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/198.mp3`}),c[807]||=i(),c[808]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[809]||=i(` Fine!`,-1),c[810]||=a(`blockquote`,null,[a(`p`,null,`很好！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/199.mp3`}),c[811]||=i(),c[812]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[813]||=i(` Yeah! (She exits.)`,-1),c[814]||=a(`blockquote`,null,[a(`p`,null,`是啊！（她离开了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/200.mp3`}),c[815]||=i(),c[816]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[817]||=i(` (to the waiter) What are you still doin’ here?! I told you, lobster ravioli!`,-1),c[818]||=a(`blockquote`,null,[a(`p`,null,`（对服务员）你还在这里干什么？！我告诉过你，龙虾水饺！`)],-1),c[819]||=a(`hr`,null,null,-1),c[820]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Outside Central Perk, Phoebe is running up to meet David.`)],-1),c[821]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`在中央公园外，菲比正跑过来迎接大卫。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/201.mp3`}),c[822]||=i(),c[823]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[824]||=i(` Hey!`,-1),c[825]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/202.mp3`}),c[826]||=i(),c[827]||=a(`strong`,null,`David:`,-1),c[828]||=i(` Hey! Oh, I was just about to leave. I-I-I-I didn’t think you were coming.`,-1),c[829]||=a(`blockquote`,null,[a(`p`,null,`嘿！哦，我正要离开。我没想到你会来。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/203.mp3`}),c[830]||=i(),c[831]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[832]||=i(` Oh, I wouldn’t miss this.`,-1),c[833]||=a(`blockquote`,null,[a(`p`,null,`哦，我不会错过这个的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/204.mp3`}),c[834]||=i(),c[835]||=a(`strong`,null,`David:`,-1),c[836]||=i(` Well, I’m very glad you’re here. (Kisses her hand.)`,-1),c[837]||=a(`blockquote`,null,[a(`p`,null,`我很高兴你在这里。（吻了吻她的手。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/205.mp3`}),c[838]||=i(),c[839]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[840]||=i(` Oh, you’re such a gentleman. (Grabs his arm.) Come on! We’re going to my place! (Drags him off to her place.)`,-1),c[841]||=a(`blockquote`,null,[a(`p`,null,`哦，你真是个绅士。（抓住他的手臂）快点！我们要去我家！（把他拖到她的地方。）`)],-1),c[842]||=a(`hr`,null,null,-1),c[843]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, Rachel is eating the cheesecake and Chandler enters and catches her in the act.`)],-1),c[844]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋家，瑞秋正在吃奶酪蛋糕，钱德勒进来，当场抓住了她。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/206.mp3`}),c[845]||=i(),c[846]||=a(`strong`,null,`Chandler Bing:`,-1),c[847]||=i(` Are you eating the cheesecake without me?!`,-1),c[848]||=a(`blockquote`,null,[a(`p`,null,`你是在没有我的情况下吃奶酪蛋糕吗？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/207.mp3`}),c[849]||=i(),c[850]||=a(`strong`,null,`Rachel Green:`,-1),c[851]||=i(` (with a mouthful) Mm-mmm. (Nods no.)`,-1),c[852]||=a(`blockquote`,null,[a(`p`,null,`（满嘴）嗯。（点头反对）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/208.mp3`}),c[853]||=i(),c[854]||=a(`strong`,null,`Chandler Bing:`,-1),c[855]||=i(` I will give you a hundred dollars to whistle right now. (She tries to whistle and blows little chunks of cheesecake out of her mouth.) How can you eat the cheesecake without me?!`,-1),c[856]||=a(`blockquote`,null,[a(`p`,null,`我现在就给你一百美元。（她试着吹口哨，嘴里吐出一小块奶酪蛋糕。）没有我，你怎么能吃奶酪蛋糕？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/209.mp3`}),c[857]||=i(),c[858]||=a(`strong`,null,`Rachel Green:`,-1),c[859]||=i(` Oh, what are you going to do?! Are you gonna go run tell Monica?! Are you gonna tell Joey?! No! Because then you will have to tell them what we did! We are desert stealers! We are living outside the law!`,-1),c[860]||=a(`blockquote`,null,[a(`p`,null,`哦，你打算怎么办？！你要去告诉莫妮卡吗？！你要告诉乔伊吗？！不因为那样你就得告诉他们我们做了什么！我们是沙漠盗贼！我们生活在法律之外！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/210.mp3`}),c[861]||=i(),c[862]||=a(`strong`,null,`Chandler Bing:`,-1),c[863]||=i(` Y’know what? I don’t trust you with this cake anymore! And I got it first, and I’m takin’ it back! (Grabs the cheesecake and heads for his apartment.)`,-1),c[864]||=a(`blockquote`,null,[a(`p`,null,`你知道吗？我再也不相信你会做这个蛋糕了！我先拿到的，我要拿回来！（抓起奶酪蛋糕，朝他的公寓走去。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/211.mp3`}),c[865]||=i(),c[866]||=a(`strong`,null,`Rachel Green:`,-1),c[867]||=i(` What?! What?!`,-1),c[868]||=a(`blockquote`,null,[a(`p`,null,`什么？！什么？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/212.mp3`}),c[869]||=i(),c[870]||=a(`strong`,null,`Chandler Bing:`,-1),c[871]||=i(` Oh yes!`,-1),c[872]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/213.mp3`}),c[873]||=i(),c[874]||=a(`strong`,null,`Rachel Green:`,-1),c[875]||=i(` Wait a minute!`,-1),c[876]||=a(`blockquote`,null,[a(`p`,null,`等一下！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/214.mp3`}),c[877]||=i(),c[878]||=a(`strong`,null,`Chandler Bing:`,-1),c[879]||=i(` Oh yes!`,-1),c[880]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/215.mp3`}),c[881]||=i(),c[882]||=a(`strong`,null,`Rachel Green:`,-1),c[883]||=i(` Oh no-no-no-no-no, no you don’t!`,-1),c[884]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，不，你没有！`)],-1),c[885]||=a(`p`,null,`[Cut to Chandler and Monica’s as they enter.]`,-1),c[886]||=a(`blockquote`,null,[a(`p`,null,`[切到钱德勒和莫妮卡家，他们进来了。]`)],-1),r(p,{src:`/audio/friends/S07/S07E11/216.mp3`}),c[887]||=i(),c[888]||=a(`strong`,null,`Chandler Bing:`,-1),c[889]||=i(` Oh yes! Oh yes!`,-1),c[890]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！哦，是的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/217.mp3`}),c[891]||=i(),c[892]||=a(`strong`,null,`Rachel Green:`,-1),c[893]||=i(` You think I trust you with it?! No! We’re gonna split it! You take half and I take half!`,-1),c[894]||=a(`blockquote`,null,[a(`p`,null,`你以为我信任你吗？！不我们要分了！你拿一半，我拿一半！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/218.mp3`}),c[895]||=i(),c[896]||=a(`strong`,null,`Chandler Bing:`,-1),c[897]||=i(` Well that’s not fair, you’ve already had some!`,-1),c[898]||=a(`blockquote`,null,[a(`p`,null,`这不公平，你已经吃过了！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/219.mp3`}),c[899]||=i(),c[900]||=a(`strong`,null,`Rachel Green:`,-1),c[901]||=i(` What? Oh, well then y’know what? I think Monica would be very interested to know that you called her cheesecake dry and mealy.`,-1),c[902]||=a(`blockquote`,null,[a(`p`,null,`什么？哦，那你知道吗？我想莫妮卡会很有兴趣知道你叫她干奶酪蛋糕。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/220.mp3`}),c[903]||=i(),c[904]||=a(`strong`,null,`Chandler Bing:`,-1),c[905]||=i(` What do we use to split it?`,-1),c[906]||=a(`blockquote`,null,[a(`p`,null,`我们用什么来分割它？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/221.mp3`}),c[907]||=i(),c[908]||=a(`strong`,null,`Rachel Green:`,-1),c[909]||=i(` Okay! (Grabs a knife and cuts it in half.) All right, pick a half.`,-1),c[910]||=a(`blockquote`,null,[a(`p`,null,`好的！（抓起一把刀，把它切成两半）好的，挑一半。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/222.mp3`}),c[911]||=i(),c[912]||=a(`strong`,null,`Chandler Bing:`,-1),c[913]||=i(` (examining the cake) Okay well, this side looks bigger. Uh… There’s more crust on this side. Y’know? So, maybe if I measured…`,-1),c[914]||=a(`blockquote`,null,[a(`p`,null,`（检查蛋糕）好吧，这边看起来更大。呃…这边有更多的外壳。你知道吗？所以，如果我测量一下…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/223.mp3`}),c[915]||=i(),c[916]||=a(`strong`,null,`Rachel Green:`,-1),c[917]||=i(` Oh for God sake just pick a piece!`,-1),c[918]||=a(`blockquote`,null,[a(`p`,null,`看在上帝的份上，挑一块吧！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/224.mp3`}),c[919]||=i(),c[920]||=a(`strong`,null,`Chandler Bing:`,-1),c[921]||=i(` All right, I’ll pick that one. (Points.)`,-1),c[922]||=a(`blockquote`,null,[a(`p`,null,`好吧，我就选那个。（点数）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/225.mp3`}),c[923]||=i(),c[924]||=a(`strong`,null,`Rachel Green:`,-1),c[925]||=i(` That’s also the smaller piece. (Puts the piece onto a plate.) Okay, there you go. Enjoy your half my friend, but that is it. No sharing. No switching, and don’t come crying to me if you eat your piece to fast. (As she’s saying that she is backing out the door, when she finishes she turns around to return to her place, stumbles and drops the cheesecake on the floor.) Oh!!!!`,-1),c[926]||=a(`blockquote`,null,[a(`p`,null,`那也是小一点的。（把这块放在盘子上）好了，开始吧。享受你的一半，我的朋友，但仅此而已。没有分享。不要换衣服，如果你吃得太快，也不要向我哭诉。（正如她说的，她正在退门，当她完成时，她转身回到自己的位置，绊倒了，把奶酪蛋糕掉在了地板上。）哦！！！！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/226.mp3`}),c[927]||=i(),c[928]||=a(`strong`,null,`Chandler Bing:`,-1),c[929]||=i(` (gloatingly and holding his piece) Ohhh!`,-1),c[930]||=a(`blockquote`,null,[a(`p`,null,`（幸灾乐祸地拿着他的作品）哦！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/227.mp3`}),c[931]||=i(),c[932]||=a(`strong`,null,`Rachel Green:`,-1),c[933]||=i(` Okay, you gotta give me some of your piece.`,-1),c[934]||=a(`blockquote`,null,[a(`p`,null,`好吧，你得给我一些你的作品。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/228.mp3`}),c[935]||=i(),c[936]||=a(`strong`,null,`Chandler Bing:`,-1),c[937]||=i(` Oh-ho-ho-ho-no! No! No switching! No sharing, and don’t come crying to me! Ha-ha-ha! I may just sit here and have my cake all day! Just sit here in the hallway and eat my… (Rachel knocks the plate from his hand and it falls on the floor. That process leaves just the forkful Chandler has, Rachel starts to go after that little bit and Chandler retreats into his apartment.)`,-1),c[938]||=a(`blockquote`,null,[a(`p`,null,`哦，呵呵，不！不禁止转换！不要分享，也不要哭着来找我！哈哈哈！我可以整天坐在这里吃蛋糕！就坐在走廊里吃我的…（瑞秋把盘子从他手上敲下来，盘子掉在地板上。这个过程只剩下钱德勒的叉子，瑞秋开始追那一点点，钱德勒回到他的公寓。）`)],-1),c[939]||=a(`hr`,null,null,-1),c[940]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Cousin Frannie’s Wedding Reception, Monica and Ross are sitting at the table, alone as a woman approaches.`)],-1),c[941]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`堂兄弗兰尼的婚礼招待会上，莫妮卡和罗斯独自坐在桌旁，一位女士走近。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/229.mp3`}),c[942]||=i(),c[943]||=a(`strong`,null,`The Woman:`,-1),c[944]||=i(` Ross, sweetheart!`,-1),c[945]||=a(`blockquote`,null,[a(`p`,null,`罗斯，亲爱的！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/230.mp3`}),c[946]||=i(),c[947]||=a(`strong`,null,`Ross Geller:`,-1),c[948]||=i(` Oh, hey Aunt Millie.`,-1),c[949]||=a(`blockquote`,null,[a(`p`,null,`噢，嘿，米莉阿姨。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/231.mp3`}),c[950]||=i(),c[951]||=a(`strong`,null,`Aunt Millie:`,-1),c[952]||=i(` Isn’t it a beautiful wedding?!`,-1),c[953]||=a(`blockquote`,null,[a(`p`,null,`这不是一场美丽的婚礼吗？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/232.mp3`}),c[954]||=i(),c[955]||=a(`strong`,null,`Ross Geller:`,-1),c[956]||=i(` Yes, yes it is. It’s uh… (Aunt Millie uses this opportunity to grab Ross and kiss him on the lips. After she leaves Ross quickly wipes his mouth with a napkin.) Every time on the lips! Why?! Why on lips?!`,-1),c[957]||=a(`blockquote`,null,[a(`p`,null,`是的，是的。嗯…（米莉阿姨利用这个机会抓住罗斯，亲吻他的嘴唇。在她离开后，罗斯迅速用餐巾擦了擦他的嘴。）每次都是在嘴唇上！为什么？为什么在嘴唇上？！`)],-1),c[958]||=a(`p`,null,[a(`em`,null,`(Cousin Frannie and her husband enter.)`)],-1),c[959]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（表哥弗兰妮和她的丈夫进来了。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/233.mp3`}),c[960]||=i(),c[961]||=a(`strong`,null,`Monica Geller:`,-1),c[962]||=i(` Here’s Frannie. Hmm, won’t she be happy to see me? (Starts to get up and great Frannie.)`,-1),c[963]||=a(`blockquote`,null,[a(`p`,null,`这是弗兰妮。嗯，她见到我不高兴吗？（开始站起来，很高兴见到弗兰妮。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/234.mp3`}),c[964]||=i(),c[965]||=a(`strong`,null,`Ross Geller:`,-1),c[966]||=i(` Now wait a minute, you be nice! All right? I didn’t bring you here so you can ambush her.`,-1),c[967]||=a(`blockquote`,null,[a(`p`,null,`等一下，你要乖一点！好吧我带你来不是为了让你伏击她。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/235.mp3`}),c[968]||=i(),c[969]||=a(`strong`,null,`Monica Geller:`,-1),c[970]||=i(` Frannie was the one who found your Playboys and showed them to mom.`,-1),c[971]||=a(`blockquote`,null,[a(`p`,null,`弗兰妮是找到你的花花公子并把他们给妈妈看的那个人。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/236.mp3`}),c[972]||=i(),c[973]||=a(`strong`,null,`Ross Geller:`,-1),c[974]||=i(` That bitch! (He gets up and they go over to ambush Frannie. Monica taps on Frannie’s shoulder.)`,-1),c[975]||=a(`blockquote`,null,[a(`p`,null,`那个婊子！（他站起来，他们去伏击弗兰尼。莫妮卡轻拍弗兰尼的肩膀。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/237.mp3`}),c[976]||=i(),c[977]||=a(`strong`,null,`Frannie:`,-1),c[978]||=i(` (turning around) Monica! What…`,-1),c[979]||=a(`blockquote`,null,[a(`p`,null,`（转过身）莫妮卡！什么…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/238.mp3`}),c[980]||=i(),c[981]||=a(`strong`,null,`Monica Geller:`,-1),c[982]||=i(` Am I doing here? Why? Surprised to see me? Ross brought me. How do you like that?!`,-1),c[983]||=a(`blockquote`,null,[a(`p`,null,`我在这里干什么？为什么？看到我很惊讶？罗斯把我带来了。你觉得怎么样？！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/239.mp3`}),c[984]||=i(),c[985]||=a(`strong`,null,`Ross Geller:`,-1),c[986]||=i(` (to Frannie) Hi Frannie, congratulations.`,-1),c[987]||=a(`blockquote`,null,[a(`p`,null,`（对弗兰妮）嗨，弗兰妮，恭喜你。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/240.mp3`}),c[988]||=i(),c[989]||=a(`strong`,null,`Monica Geller:`,-1),c[990]||=i(` You invite my brother, you invite my whole family, and not me?! Why?! What—Why wouldn’t you want me at your wedding? What could I have possibly done?! (Frannie’s husband walks up.) Stuart!`,-1),c[991]||=a(`blockquote`,null,[a(`p`,null,`你邀请我哥哥，你邀请我全家，而不是我？！为什么？你为什么不让我参加你的婚礼？我能做什么？！（弗兰妮的丈夫走了过来。）斯图尔特！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/241.mp3`}),c[992]||=i(),c[993]||=a(`strong`,null,`Frannie:`,-1),c[994]||=i(` I believe you know my husband.`,-1),c[995]||=a(`blockquote`,null,[a(`p`,null,`我相信你认识我丈夫。`)],-1),c[996]||=a(`p`,null,[a(`em`,null,`(Monica is shocked into silence.)`)],-1),c[997]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡震惊地沉默了。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/242.mp3`}),c[998]||=i(),c[999]||=a(`strong`,null,`Ross Geller:`,-1),c[1e3]||=i(` So it’s really a question of who could you have possibly done.`,-1),c[1001]||=a(`blockquote`,null,[a(`p`,null,`所以这真的是一个问题，你可能做了什么。`)],-1),c[1002]||=a(`hr`,null,null,-1),c[1003]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Outside Central Perk, David has a cab waiting to take him to the airport and he’s saying goodbye to Phoebe.`)],-1),c[1004]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`在中央公园外，大卫有一辆出租车等着送他去机场，他正在和菲比道别。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/243.mp3`}),c[1005]||=i(),c[1006]||=a(`strong`,null,`David:`,-1),c[1007]||=i(` Oh, I hate this but I-I-I have to go. I-I can’t miss my flight.`,-1),c[1008]||=a(`blockquote`,null,[a(`p`,null,`噢，我讨厌这个，但我，我，我得走了。我不能错过我的航班。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/244.mp3`}),c[1009]||=i(),c[1010]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1011]||=i(` Are you sure? I’ll bet there’s another flight to Minsk in like…`,-1),c[1012]||=a(`blockquote`,null,[a(`p`,null,`你确定吗？我敢打赌明天还有一班飞往明斯克的航班…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/245.mp3`}),c[1013]||=i(),c[1014]||=a(`strong`,null,`David:`,-1),c[1015]||=i(` July. Umm, (He speaks Russian.)`,-1),c[1016]||=a(`blockquote`,null,[a(`p`,null,`七月。嗯，（他说俄语。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/246.mp3`}),c[1017]||=i(),c[1018]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1019]||=i(` That’s really beautiful. What does it mean?`,-1),c[1020]||=a(`blockquote`,null,[a(`p`,null,`真漂亮。这是什么意思？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/247.mp3`}),c[1021]||=i(),c[1022]||=a(`strong`,null,`David:`,-1),c[1023]||=i(` Please, clean my beakers. I don’t get out of the lab much.`,-1),c[1024]||=a(`blockquote`,null,[a(`p`,null,`请把我的烧杯洗干净。我很少离开实验室。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/248.mp3`}),c[1025]||=i(),c[1026]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1027]||=i(` That’s good. I got to admit, I thought it was something else.`,-1),c[1028]||=a(`blockquote`,null,[a(`p`,null,`那很好。我得承认，我还以为是别的。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/249.mp3`}),c[1029]||=i(),c[1030]||=a(`strong`,null,`David:`,-1),c[1031]||=i(` Yeah, I… Well I really actually wanted to say umm, that, but um, I figured I probably shouldn’t because y’know, I…have to leave.`,-1),c[1032]||=a(`blockquote`,null,[a(`p`,null,`是的，我…嗯，我真的很想说，嗯，但是，嗯，我想我可能不应该说，因为你知道，我…必须离开。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/250.mp3`}),c[1033]||=i(),c[1034]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1035]||=i(` You’re right! You’re right. Don’t say it.`,-1),c[1036]||=a(`blockquote`,null,[a(`p`,null,`你说得对！你说得对。别说了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/251.mp3`}),c[1037]||=i(),c[1038]||=a(`strong`,null,`David:`,-1),c[1039]||=i(` I-I do though.`,-1),c[1040]||=a(`blockquote`,null,[a(`p`,null,`不过我知道。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/252.mp3`}),c[1041]||=i(),c[1042]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1043]||=i(` I do too. (They kiss.)`,-1),c[1044]||=a(`blockquote`,null,[a(`p`,null,`我也是。（他们接吻。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/253.mp3`}),c[1045]||=i(),c[1046]||=a(`strong`,null,`David:`,-1),c[1047]||=i(` Bye Phoebe. (He gets in and the cab drives off. Joey walks up and witnesses that event.)`,-1),c[1048]||=a(`blockquote`,null,[a(`p`,null,`再见，菲比。（他上车，出租车开走了。乔伊走上前，目睹了这一事件。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/254.mp3`}),c[1049]||=i(),c[1050]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1051]||=i(` (seeing him) Okay, now’s not the time Joey. All right? You can yell at me tomorrow.`,-1),c[1052]||=a(`blockquote`,null,[a(`p`,null,`（看着他）好吧，现在不是乔伊的时候。好吧明天你可以对我大喊大叫。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/255.mp3`}),c[1053]||=i(),c[1054]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1055]||=i(` No! No! No Pheebs, I’m not gonna yell at you. I just y’know, started thinking about you and David and I…remember how bummed you were the first time he left. And I just… Oh Pheebs, come here. (He hugs her.) Are you okay?`,-1),c[1056]||=a(`blockquote`,null,[a(`p`,null,`不！不不，菲比，我不会对你大喊大叫的。我刚开始想你和大卫，我还记得他第一次离开时你有多沮丧。我只是…哦，菲比，过来。（他拥抱她）你没事吧？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/256.mp3`}),c[1057]||=i(),c[1058]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1059]||=i(` No I’m not okay. The only guy I’ve ever been crazy about has gone to Minsk and I may never…I may never see him again. (Crying.)`,-1),c[1060]||=a(`blockquote`,null,[a(`p`,null,`不，我不好。我唯一迷恋的人去了明斯克，我可能再也见不到他了。（哭着。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/257.mp3`}),c[1061]||=i(),c[1062]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1063]||=i(` Hey, y’know you could always visit him.`,-1),c[1064]||=a(`blockquote`,null,[a(`p`,null,`嘿，你知道你随时都可以去看他。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/258.mp3`}),c[1065]||=i(),c[1066]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1067]||=i(` Oh right, like they’re gonna let me have a passport.`,-1),c[1068]||=a(`blockquote`,null,[a(`p`,null,`哦，对了，好像他们要给我一本护照。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/259.mp3`}),c[1069]||=i(),c[1070]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1071]||=i(` Anything I can do? Whatever you need.`,-1),c[1072]||=a(`blockquote`,null,[a(`p`,null,`我能做什么？你需要什么都行。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/260.mp3`}),c[1073]||=i(),c[1074]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1075]||=i(` Well—But—Now, if-if you can achieve positronic distillation of sub-atomic particles y’know before he does, then he can come back. (They hug again.)`,-1),c[1076]||=a(`blockquote`,null,[a(`p`,null,`但是现在，如果你能在他之前实现亚原子粒子的正电子蒸馏，那么他就可以回来了。（他们又拥抱了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/261.mp3`}),c[1077]||=i(),c[1078]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1079]||=i(` I can give it a shot.`,-1),c[1080]||=a(`blockquote`,null,[a(`p`,null,`我可以试一试。`)],-1),c[1081]||=a(`hr`,null,null,-1),c[1082]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Hallway, Chandler and Rachel are on their knees with forks trying to salvage what they can of the cheesecake off of the floor.`)],-1),c[1083]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`走廊上，钱德勒和瑞秋跪在地上，拿着叉子试图从地板上尽可能多地捞起奶酪蛋糕。`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/262.mp3`}),c[1084]||=i(),c[1085]||=a(`strong`,null,`Rachel Green:`,-1),c[1086]||=i(` Oh! Yay! Look! There’s a piece that doesn’t have floor on it!`,-1),c[1087]||=a(`blockquote`,null,[a(`p`,null,`哦！耶！看！有一块上面没有地板！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/263.mp3`}),c[1088]||=i(),c[1089]||=a(`strong`,null,`Chandler Bing:`,-1),c[1090]||=i(` Stick to your side!`,-1),c[1091]||=a(`blockquote`,null,[a(`p`,null,`站在你这边！`)],-1),r(p,{src:`/audio/friends/S07/S07E11/264.mp3`}),c[1092]||=i(),c[1093]||=a(`strong`,null,`Rachel Green:`,-1),c[1094]||=i(` Hey, come on now!`,-1),c[1095]||=a(`blockquote`,null,[a(`p`,null,`嘿，快点！`)],-1),c[1096]||=a(`p`,null,[a(`em`,null,`(Joey finishes climbing the stairs and sees them. Chandler and Rachel both stop and look up at him. Joey sits down on the step.)`)],-1),c[1097]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊爬完楼梯，看到了他们。钱德勒和瑞秋都停下来，抬头看着他。乔伊坐在台阶上。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/265.mp3`}),c[1098]||=t(` <strong>Joey Tribbiani:</strong> (pulls out a fork) All right, what are we havin’? (Starts digging in.)<blockquote><p>（拿出叉子）好吧，我们吃什么？（开始挖掘。）</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Cousin Frannie’s Wedding Reception, Ross and Monica are at the door and about to leave.</em></p><blockquote><p>🎬 <em>表哥弗兰尼的婚宴，罗斯和莫妮卡在门口，准备离开。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E11/266.mp3`}),c[1099]||=i(),c[1100]||=a(`strong`,null,`Monica Geller:`,-1),c[1101]||=i(` Oh wait I forgot my wrap.`,-1),c[1102]||=a(`blockquote`,null,[a(`p`,null,`哦，等等，我忘带包裹了。`)],-1),r(p,{src:`/audio/friends/S07/S07E11/267.mp3`}),c[1103]||=i(),c[1104]||=a(`strong`,null,`Ross Geller:`,-1),c[1105]||=i(` What? Oh, okay. Wait here. (Goes to get it, but before he gets there Aunt Millie sits down on it forcing him to pull it out from behind her which gets her attention.)`,-1),c[1106]||=a(`blockquote`,null,[a(`p`,null,`什么？哦，好的。在这儿等着。（他去拿，但在他到达之前，米莉姨妈坐在上面，强迫他从她身后把它拔出来，这引起了她的注意。）`)],-1),r(p,{src:`/audio/friends/S07/S07E11/268.mp3`}),c[1107]||=i(),c[1108]||=a(`strong`,null,`Aunt Millie:`,-1),c[1109]||=i(` Hi sweetie! Are you leaving?`,-1),c[1110]||=a(`blockquote`,null,[a(`p`,null,`嗨，亲爱的！你要离开吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E11/269.mp3`}),c[1111]||=i(),c[1112]||=a(`strong`,null,`Ross Geller:`,-1),c[1113]||=i(` Well…`,-1),c[1114]||=a(`blockquote`,null,[a(`p`,null,`嗯…`)],-1),r(p,{src:`/audio/friends/S07/S07E11/270.mp3`}),c[1115]||=i(),c[1116]||=a(`strong`,null,`Aunt Millie:`,-1),c[1117]||=i(` Give us a kiss. Come on! Come on!`,-1),c[1118]||=a(`blockquote`,null,[a(`p`,null,`给我们一个吻。来吧来吧`)],-1),c[1119]||=a(`p`,null,[a(`em`,null,`(Ross hesitates then leans down trying to get her to kiss his cheek, but she moves his head around and kisses him on the lips again.)`)],-1),c[1120]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯犹豫了一下，然后弯下身试图让她亲吻他的脸颊，但她移动了他的头，再次亲吻了他的嘴唇。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E11/271.mp3`}),c[1121]||=i(),c[1122]||=a(`strong`,null,`Ross Geller:`,-1),c[1123]||=i(` Why?! Why on the lips?! (He wipes his mouth on Monica’s wrap and walks off, leaving Aunt Millie stunned.)`,-1),c[1124]||=a(`blockquote`,null,[a(`p`,null,`为什么？！为什么在嘴上？！（他在莫妮卡的包裹上擦了擦嘴就走了，让米莉姨妈目瞪口呆。）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};